WITH with_windows AS (SELECT *, NTILE(3) OVER (ORDER BY cost, id) AS cost_bucket, CUME_DIST() OVER (PARTITION BY status ORDER BY cost DESC) AS cost_cume_dist, SUM(cost) OVER (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost, DENSE_RANK() OVER (PARTITION BY status, carrier ORDER BY cost NULLS FIRST) AS cost_dense_rank FROM shipments) SELECT id, order_id, shipped_date, delivered_date, status, cost_bucket, cost_cume_dist, cumulative_cost, cost_dense_rank, CASE WHEN status RLIKE '^(IN_TRANSIT|DELIVERED)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS status_zone FROM with_windows ORDER BY cumulative_cost NULLS FIRST;
